    public override int GetHashCode() => _si.GetHashCode();
    public int CompareTo(Ratio other) => _si.CompareTo(other._si);
    public int CompareTo(object? obj) => obj is Ratio other ? CompareTo(other) : throw new ArgumentException($"Can't compare Ratio with {obj?.GetType().Name ?? "null"}");

    // ---- Text ----
    /// <summary>SI value with 4 significant digits, e.g. "1.5 kW" is printed as "1500 W".</summary>
    public override string ToString() => ToString(null, null);
    public string ToString(IFormatProvider formatProvider) => ToString(null, formatProvider);
    public string ToString(string? format) => ToString(format, null);
    public string ToString(string? format, IFormatProvider? formatProvider) => QuantityFormatter.Format(_si, RatioUnit.SI.Symbol, format, formatProvider);
    /// <summary>The value in <paramref name="unit"/>, e.g. "1.5 kW".</summary>
    public string ToString(RatioUnit unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

    /// <summary>
    /// The same value, shown in <paramref name="unit"/>: <c>$"{p.ToUnit(PressureUnit.Bar)}"</c> prints "2 bar". Values are always
    /// stored in SI, so this is a display wrapper - it converts back to Ratio, but math on it needs the Ratio first.
    /// </summary>
    public QuantityInUnit<Ratio> ToUnit(RatioUnit unit) => new(this, unit);

    /// <summary>The value in SI. (A decimal in EngineeringUnits; the same number as <see cref="SI"/> here.)</summary>
    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public double AsSI => _si;

    /// <summary>Returns the same value: it is always stored in SI. (EngineeringUnits converts the unit here.)</summary>
    public Ratio ConvertToSI() => this;

}

/// <summary>Writes {"Value": si, "Unit": ""}. Reads that (any unit of Ratio, by exact symbol) or a bare SI number - a unit of another quantity is rejected.</summary>
public sealed class RatioJsonConverter : JsonConverter<Ratio>
{
    public override Ratio Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        => Ratio.FromSI(QuantityJson.Read(ref reader, "Ratio", RatioUnit.BySymbol));

    public override void Write(Utf8JsonWriter writer, Ratio value, JsonSerializerOptions options)
        => QuantityJson.Write(writer, value.SI, RatioUnit.SI.Symbol);
}

public static partial class UnitMath
{
    [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
    public static UnknownUnit Pow(this Ratio value, int toPower) => new(Math.Pow(value.SI, toPower));

    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this Ratio value) => new(Math.Sqrt(value.SI));

    public static Ratio Sum(this IEnumerable<Ratio> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return Ratio.FromSI(sum);
    }

    public static Ratio Average(this IEnumerable<Ratio> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : Ratio.FromSI(sum / count);
    }

    public static Ratio Min(this IEnumerable<Ratio> values) => Aggregate(values, Math.Min);
    public static Ratio Max(this IEnumerable<Ratio> values) => Aggregate(values, Math.Max);

    private static Ratio Aggregate(IEnumerable<Ratio> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return Ratio.FromSI(result);
    }
}
